Here is the commit message:
thermal: core: Fix thermal zone device registration error
 path

If thermal_zone_device_register_with_trips() fails after registering
a thermal zone device, it needs to wait for the tz->removal completion
like thermal_zone_device_unregister(), in case user space has managed
to take a reference to the thermal zone device's kobject, in which case
thermal_release() may not be called by the error path itself and tz may
be freed prematurely.

Add the missing wait_for_completion() call to the thermal zone device
registration error path.

Fixes: 04e6ccfc93c5 ("thermal: core: Fix NULL pointer dereference in zone registration error path")
Signed-off-by: Rafael J. Wysocki <rafael.j.wysocki@intel.com>
Cc: All applicable <stable@vger.kernel.org>
Reviewed-by: Lukasz Luba <lukasz.luba@arm.com>
Tested-by: Lukasz Luba <lukasz.luba@arm.com>
Link: https://patch.msgid.link/2849815.mvXUDI8C0e@rafael.j.wysocki

Here is the root cause:
The error path in `thermal_zone_device_register_with_trips()` after a successful device registration did not wait for the `tz->removal` completion, allowing the thermal zone device (`tz`) to be freed prematurely if user space had taken a reference to its kobject. This could lead to use-after-free or other memory corruption because the release function (`thermal_release()`) might be called asynchronously after the error path had already freed resources like the IDA and trip point data.

Here is the patch:
  */
 struct thermal_zone_device *
 thermal_zone_device_register_with_trips(const char *type,
 					const struct thermal_trip *trips,
 					int num_trips, void *devdata,
 					const struct thermal_zone_device_ops *ops,
 					const struct thermal_zone_params *tzp,
 					unsigned int passive_delay,
 					unsigned int polling_delay)
 {
 	const struct thermal_trip *trip = trips;
 	struct thermal_zone_device *tz;
 	struct thermal_trip_desc *td;
 	size_t type_len = 0;
 	int id;
 	int result;

 	if (type)
 		type_len = strnlen(type, THERMAL_NAME_LENGTH);

 	if (type_len == 0) {
 		pr_err("No thermal zone type defined\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (type_len == THERMAL_NAME_LENGTH) {
 		pr_err("Thermal zone name (%s) too long, should be under %d chars\n",
 		       type, THERMAL_NAME_LENGTH);
 		return ERR_PTR(-EINVAL);
 	}

 	if (num_trips < 0) {
 		pr_err("Incorrect number of thermal trips\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (!ops || !ops->get_temp) {
 		pr_err("Thermal zone device ops not defined or invalid\n");
 		return ERR_PTR(-EINVAL);
 	}

 	if (num_trips > 0 && !trips)
 		return ERR_PTR(-EINVAL);

 	if (polling_delay && passive_delay > polling_delay)
 		return ERR_PTR(-EINVAL);

 	if (!thermal_class)
 		return ERR_PTR(-ENODEV);

 	tz = kzalloc_flex(*tz, trips, num_trips);
 	if (!tz)
 		return ERR_PTR(-ENOMEM);

 	if (tzp) {
 		tz->tzp = kmemdup(tzp, sizeof(*tzp), GFP_KERNEL);
 		if (!tz->tzp) {
 			result = -ENOMEM;
 			goto free_tz;
 		}
 	}

 	INIT_LIST_HEAD(&tz->node);
 	INIT_LIST_HEAD(&tz->trips_high);
 	INIT_LIST_HEAD(&tz->trips_reached);
 	INIT_LIST_HEAD(&tz->trips_invalid);
 	ida_init(&tz->ida);
 	mutex_init(&tz->lock);
 	init_completion(&tz->removal);
 	init_completion(&tz->resume);
 	id = ida_alloc(&thermal_tz_ida, GFP_KERNEL);
 	if (id < 0) {
 		result = id;
 		goto free_tzp;
 	}

 	tz->id = id;
 	strscpy(tz->type, type, sizeof(tz->type));

 	tz->ops = *ops;
 	if (!tz->ops.critical)
 		tz->ops.critical = thermal_zone_device_critical;

 	tz->device.class = thermal_class;
 	tz->devdata = devdata;
 	tz->num_trips = num_trips;
 	for_each_trip_desc(tz, td) {
 		td->trip = *trip++;
 		INIT_LIST_HEAD(&td->thermal_instances);
 		INIT_LIST_HEAD(&td->list_node);
 		/*
 		 * Mark all thresholds as invalid to start with even though
 		 * this only matters for the trips that start as invalid and
 		 * become valid later.
 		 */
 		move_to_trips_invalid(tz, td);
 	}

 	tz->polling_delay_jiffies = msecs_to_jiffies(polling_delay);
 	tz->passive_delay_jiffies = msecs_to_jiffies(passive_delay);
 	tz->recheck_delay_jiffies = THERMAL_RECHECK_DELAY;

 	tz->state = TZ_STATE_FLAG_INIT;

 	result = dev_set_name(&tz->device, "thermal_zone%d", tz->id);
 	if (result)
 		goto remove_id;

 	thermal_zone_device_init(tz);

 	result = thermal_zone_init_governor(tz);
 	if (result)
 		goto remove_id;

 	/* sys I/F */
 	/* Add nodes that are always present via .groups */
 	result = thermal_zone_create_device_groups(tz);
 	if (result)
 		goto remove_id;

 	result = device_register(&tz->device);
 	if (result)
 		goto release_device;

 	if (!tz->tzp || !tz->tzp->no_hwmon) {
 		result = thermal_add_hwmon_sysfs(tz);
 		if (result)
 			goto unregister;
 	}

 	result = thermal_thresholds_init(tz);
 	if (result)
 		goto remove_hwmon;

 	thermal_zone_init_complete(tz);

 	thermal_notify_tz_create(tz);

 	thermal_debug_tz_add(tz);

 	return tz;

 remove_hwmon:
 	thermal_remove_hwmon_sysfs(tz);
 unregister:
 	device_del(&tz->device);
 release_device:
 	put_device(&tz->device);
+	wait_for_completion(&tz->removal);
 remove_id:
 	ida_free(&thermal_tz_ida, id);
 free_tzp:
 	kfree(tz->tzp);
 free_tz:
 	kfree(tz);
 	return ERR_PTR(result);
 }
 EXPORT_SYMBOL_GPL(thermal_zone_device_register_with_trips);


